import { McpServer } from "@modelcontextprotocol/server";
import type { HevyClient, HevyClientLogEvent } from "@hevy-mcp/hevy-client";
import { Cache, Effect } from "effect";
import { createOperations } from "@hevy-mcp/operations";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import { registerWorkoutPrompts } from "./prompts/workouts.js";
import { registerHevyResources } from "./resources/hevy.js";
import {
	SERVER_INSTRUCTIONS,
	SERVER_NAME,
	SERVER_VERSION,
} from "./server-metadata.js";
import { registerHevyTools } from "./tools/register.js";
import { createToolRuntime } from "./tools/tool-runtime.js";
import {
	createExerciseTemplateCatalog,
	EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
	EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
} from "./utils/exercise-template-catalog.js";
import { createMcpClientLogger } from "./utils/mcp-client-logger.js";
import type { CacheObserver } from "./utils/cache.js";
import type { ToolObserver } from "./observation.js";
export interface HevyClientFactoryContext {
	readonly onLog: (event: HevyClientLogEvent) => void;
}

export interface CreateHevyMcpServerOptions {
	readonly createClient: (context: HevyClientFactoryContext) => HevyClient;
	readonly observer?: ToolObserver;
	readonly cacheObserver?: CacheObserver;
	readonly decorateServer?: (server: McpServer) => McpServer;
	readonly onToolsRegistered?: (count: number) => void;
	/** One absolute budget for each incoming MCP invocation. */
	readonly executionTimeoutMs?: number;
	/** Absolute deadline shared by validation and every tool call in one invocation. */
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
}

function createCountingServer(server: McpServer) {
	let count = 0;
	const countingServer = new Proxy(server, {
		get(target, property, receiver) {
			if (property === "registerTool") {
				const registerTool = target.registerTool.bind(target);
				return (...args: unknown[]) => {
					const result = Reflect.apply(registerTool, target, args);
					count += 1;
					return result;
				};
			}
			return Reflect.get(target, property, receiver);
		},
	});
	return { server: countingServer, getCount: () => count };
}

export function createHevyMcpServer(
	options: CreateHevyMcpServerOptions,
): McpServer {
	const baseServer = new McpServer(
		{ name: SERVER_NAME, version: SERVER_VERSION },
		{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
	);
	const server = options.decorateServer?.(baseServer) ?? baseServer;
	const mcpLogger = createMcpClientLogger(server);
	const client = options.createClient({ onLog: (event) => mcpLogger(event) });
	const operations = createOperations(client);
	const templateListAll = operations.templates?.listAll;
	if (!templateListAll) {
		throw new Error("Exercise template list operation is unavailable.");
	}
	const cache = Effect.runSync(
		Cache.make<
			string,
			ExerciseTemplate[],
			Effect.Error<ReturnType<TemplatesListAllOperation["effect"]>>
		>({
			capacity: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
			timeToLive: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
			lookup: (_key: string) => templateListAll.effect(),
		}),
	);
	const runtime = createToolRuntime({
		client,
		operations,
		catalog: createExerciseTemplateCatalog(
			operations,
			cache,
			options.cacheObserver,
		),
		logger: mcpLogger,
		observer: options.observer,
		executionTimeoutMs: options.executionTimeoutMs,
		executionDeadline: options.executionDeadline,
		lifecycleSignal: options.lifecycleSignal,
	});
	const counting = createCountingServer(server);
	registerHevyTools(counting.server, runtime);
	options.onToolsRegistered?.(counting.getCount());
	registerWorkoutPrompts(server, options.observer);
	registerHevyResources(server, runtime);
	return server;
}

import { Context, Effect, Layer, Scope } from "effect";
import type { McpClientLogger } from "../utils/mcp-client-logger.js";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import {
	createCoreServiceLayer,
	createToolObserverLayer,
	type CoreServiceIdentifiers,
} from "../effect-layer.js";
import {
	ExerciseTemplateCatalogService,
	HevyClientService,
	HevyOperationsService,
	ToolObserverService,
} from "../effect-services.js";
import {
	HEVY_CLIENT_NOT_INITIALIZED_ERROR,
	requireClient,
} from "../utils/tool-helpers.js";
import { withErrorHandling } from "../utils/error-handler.js";
import type { ExerciseTemplateCatalog } from "../utils/exercise-template-catalog.js";
import type { McpToolResponse } from "../utils/response-contracts.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import {
	memoizeObservationScope,
	type SafeToolArgumentKey,
	type ToolObserver,
	type ToolCompletionObservation,
} from "../observation.js";
import { bucketCount, getResultTelemetry } from "../utils/result-telemetry.js";
import { resolveErrorPolicy } from "../utils/error-policy.js";
import {
	bindClientExecution,
	mergeAbortSignals,
	type ToolExecutionContext,
} from "../execution.js";
import { DEFAULT_API_TIMEOUT_MS } from "@hevy-mcp/hevy-client";
import { TELEMETRY_ARGUMENT_KEYS } from "../utils/telemetry-contract.js";
import { isBoolean, isFiniteNumber } from "../utils/type-predicates.js";

interface ArgumentKeySet {
	readonly [key: string]: true;
}

const toKeySet = (keys: readonly string[]): Readonly<ArgumentKeySet> =>
	Object.fromEntries(keys.map((key) => [key, true as const]));

const STRUCTURAL_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = toKeySet(
	TELEMETRY_ARGUMENT_KEYS,
);

const PRESENCE_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	since: true,
	workout_id: true,
	routine_id: true,
	folder_id: true,
	exercise_template_id: true,
	date: true,
	start_date: true,
	end_date: true,
	updated_since: true,
	query: true,
	primary_muscle_group: true,
};

const NUMERIC_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	page: true,
	page_size: true,
	limit: true,
	offset: true,
};

const BOOLEAN_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	include_custom: true,
	refresh: true,
};

const structuralArgumentKeys = Object.keys(
	STRUCTURAL_ARGUMENT_KEYS,
) as SafeToolArgumentKey[];

type ToolRuntimeServiceIdentifiers =
	| CoreServiceIdentifiers
	| ToolObserverService;
type ToolRuntimeServiceLayer = Layer.Layer<ToolRuntimeServiceIdentifiers>;
type ToolRuntimeServiceContext = Context.Context<ToolRuntimeServiceIdentifiers>;

function buildServiceContext(
	layer: ToolRuntimeServiceLayer,
): ToolRuntimeServiceContext {
	// Build the layer against a scope that outlives this call. `Effect.scoped`
	// would close the scope immediately, releasing any scoped resources
	// before the returned context is ever used by request handlers.
	const scope = Effect.runSync(Scope.make());
	return Effect.runSync(Scope.provide(scope)(Layer.build(layer)));
}

function createSafeInvocation<TArgs extends object>(
	name: string,
	args: TArgs,
	taxonomy: ToolTelemetryMetadata | undefined,
) {
	const argumentValues = new Map<string, unknown>(Object.entries(args));
	const argumentKeys = structuralArgumentKeys.filter((key) => key in args);
	const argumentPresence: Record<string, true> = {};
	const numericArgumentBuckets: Record<
		string,
		ReturnType<typeof bucketCount>
	> = {};
	const booleanArguments: Record<string, boolean> = {};

	for (const key of argumentKeys) {
		const value = argumentValues.get(key);
		if (
			key in PRESENCE_ARGUMENT_KEYS &&
			value !== null &&
			value !== undefined
		) {
			argumentPresence[key] = true;
		}
		if (key in NUMERIC_ARGUMENT_KEYS && isFiniteNumber(value)) {
			numericArgumentBuckets[key] = bucketCount(value);
		}
		if (key in BOOLEAN_ARGUMENT_KEYS && isBoolean(value)) {
			booleanArguments[key] = value;
		}
	}

	return {
		name,
		taxonomy,
		argumentKeys,
		argumentPresence,
		numericArgumentBuckets,
		booleanArguments,
		argumentKeyCountBucket: bucketCount(Object.keys(args).length),
	};
}

export type ToolHandler<TParams extends object = object> = (
	args: TParams,
	context?: ToolExecutionContext,
) => Promise<McpToolResponse>;

export type ToolEffectHandler<TParams extends object = object> = (
	args: TParams,
	context?: ToolExecutionContext,
) => Effect.Effect<McpToolResponse, unknown, never>;

export type ToolHandlerFactory = <TParams extends object>(
	fn: ToolEffectHandler<TParams>,
	context: string,
	metadata?: ToolTelemetryMetadata,
) => ToolHandler;
export interface ToolRuntime {
	readonly client: HevyClient | null;
	readonly catalog: ExerciseTemplateCatalog;
	/** The request-local dependency graph used by Effect-backed tool code. */
	readonly layer?: ToolRuntimeServiceLayer;
	/** The context built from `layer`, kept request-local with the runtime. */
	readonly services?: ToolRuntimeServiceContext;
	readonly logger?: McpClientLogger;
	readonly execution?: ToolExecutionContext;
	readonly executionTimeoutMs: number;
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
	readonly operations: HevyOperations | null;
	readonly createHandler: ToolHandlerFactory;
	service<I extends ToolRuntimeServiceIdentifiers, S>(
		service: Context.Key<I, S>,
	): S;
	getClient(): HevyClient;
	getOperations(): HevyOperations;
	forExecution(context?: ToolExecutionContext): ToolRuntime;
}

export interface CreateToolRuntimeOptions {
	client: HevyClient | null;
	/** Unbound client retained across nested execution scopes. */
	baseClient?: HevyClient | null;
	operations?: HevyOperations;
	catalog: ExerciseTemplateCatalog;
	logger?: McpClientLogger;
	createHandler?: ToolHandlerFactory;
	observer?: ToolObserver;
	execution?: ToolExecutionContext;
	executionTimeoutMs?: number;
	executionDeadline?: number;
	lifecycleSignal?: AbortSignal;
}

function runToolEffect<TParams extends object>(
	fn: ToolEffectHandler<TParams>,
	args: TParams,
	requestContext: ToolExecutionContext | undefined,
	services: ToolRuntimeServiceContext | undefined,
): Promise<McpToolResponse> {
	const program = Effect.suspend(() => fn(args, requestContext));
	const provided = services ? Effect.provide(program, services) : program;
	return Effect.runPromise(provided);
}

export const defaultHandlerFactory: ToolHandlerFactory = <
	TParams extends object,
>(
	fn: ToolEffectHandler<TParams>,
	context: string,
) =>
	withErrorHandling(
		(args: TParams, requestContext?: ToolExecutionContext) =>
			runToolEffect(fn, args, requestContext, undefined),
		context,
	) as ToolHandler;

export function createToolRuntime({
	client,
	baseClient,
	operations,
	catalog,
	logger,
	createHandler,
	observer,
	execution,
	executionTimeoutMs = DEFAULT_API_TIMEOUT_MS,
	executionDeadline,
	lifecycleSignal,
}: CreateToolRuntimeOptions): ToolRuntime {
	const rawClient = baseClient ?? client;
	const resolvedOperations =
		operations ?? (rawClient ? createOperations(rawClient) : null);
	const effectiveExecutionDeadline = executionDeadline ?? execution?.deadline;
	const effectiveClient =
		execution && rawClient
			? bindClientExecution(requireClient(rawClient), execution)
			: client;
	const effectiveCatalog = execution
		? {
				effect: (options = {}) => catalog.effect({ ...options, execution }),
				get: (options = {}) => catalog.get({ ...options, execution }),
				reset: () => catalog.reset(),
			}
		: catalog;
	const coreLayer =
		effectiveClient && resolvedOperations
			? (createCoreServiceLayer({
					client: effectiveClient,
					catalog: effectiveCatalog,
					execution: execution ?? {},
					operations: resolvedOperations,
				}) as ToolRuntimeServiceLayer)
			: resolvedOperations
				? (Layer.mergeAll(
						Layer.succeed(HevyOperationsService, resolvedOperations),
						Layer.succeed(ExerciseTemplateCatalogService, effectiveCatalog),
					) as ToolRuntimeServiceLayer)
				: (Layer.succeed(
						ExerciseTemplateCatalogService,
						effectiveCatalog,
					) as ToolRuntimeServiceLayer);
	const layer = observer
		? coreLayer
			? (Layer.merge(
					coreLayer,
					createToolObserverLayer(observer),
				) as ToolRuntimeServiceLayer)
			: (createToolObserverLayer(observer) as ToolRuntimeServiceLayer)
		: coreLayer;
	const services = layer ? buildServiceContext(layer) : undefined;
	const effectHandlerFactory: ToolHandlerFactory =
		createHandler ??
		(<TParams extends object>(
			fn: ToolEffectHandler<TParams>,
			context: string,
		) =>
			withErrorHandling(
				(args: TParams, requestContext?: ToolExecutionContext) =>
					runToolEffect(fn, args, requestContext, services),
				context,
			) as ToolHandler);
	const getService = <I extends ToolRuntimeServiceIdentifiers, S>(
		service: Context.Key<I, S>,
	): S => {
		if (service.key === HevyClientService.key) {
			requireClient(effectiveClient);
		}
		if (!services) {
			throw new Error("Core service layer is unavailable");
		}
		return Context.get(services, service);
	};
	const createObservedHandler: ToolHandlerFactory = <TParams extends object>(
		fn: ToolEffectHandler<TParams>,
		context: string,
		metadata?: ToolTelemetryMetadata,
	) => {
		// Compose observation around the resolved handler factory so a
		// caller-supplied `createHandler` stays in the path when an observer is
		// configured; without one, the raw effect runner preserves the default
		// withErrorHandling observation semantics.
		const resolvedHandler: (
			args: TParams,
			requestContext?: ToolExecutionContext,
		) => Promise<McpToolResponse> = createHandler
			? createHandler(fn, context, metadata)
			: (args, requestContext) =>
					runToolEffect(fn, args, requestContext, services);
		return withErrorHandling(
			async (args: TParams, requestContext?: ToolExecutionContext) => {
				let scope;
				try {
					scope = memoizeObservationScope(
						observer?.start(createSafeInvocation(context, args, metadata)),
					);
				} catch {
					scope = undefined;
				}
				const startedAt = Date.now();
				let handlerPromise: Promise<McpToolResponse> | undefined;
				const invokeHandler = () => {
					handlerPromise ??= resolvedHandler(args, requestContext);
					return handlerPromise;
				};
				try {
					let runPromise: Promise<McpToolResponse>;
					if (scope) {
						try {
							runPromise = scope.run(invokeHandler);
						} catch {
							runPromise = invokeHandler();
						}
					} else {
						runPromise = invokeHandler();
					}
					const result = await runPromise.catch(invokeHandler);
					const telemetry = {
						outcome: result.isError ? "returned_error" : "success",
						durationMs: Date.now() - startedAt,
						errorOutcome: result.errorOutcome,
						result: {
							isError: Boolean(result.isError),
							hasStructuredContent: result.structuredContent !== undefined,
							contentCountBucket: bucketCount(result.content.length),
							summary: getResultTelemetry(result),
						},
					} satisfies ToolCompletionObservation;
					void scope?.finish(telemetry);
					return result;
				} catch (error) {
					const policy = resolveErrorPolicy(error, "");
					void scope?.finish({
						outcome: "thrown_error",
						durationMs: Date.now() - startedAt,
						errorType: policy.type,
						error: policy.diagnostic,
					});
					throw error;
				}
			},
			context,
		) as ToolHandler;
	};
	const observedHandlerFactory = observer
		? createObservedHandler
		: effectHandlerFactory;
	const runtime: ToolRuntime = {
		client: effectiveClient,
		catalog: effectiveCatalog,
		layer,
		services,
		logger,
		execution,
		executionTimeoutMs,
		executionDeadline: effectiveExecutionDeadline,
		lifecycleSignal,
		operations: resolvedOperations,
		createHandler: observedHandlerFactory,
		service: getService,
		getClient: () =>
			effectiveClient && services
				? getService(HevyClientService)
				: requireClient(effectiveClient),
		getOperations: () =>
			resolvedOperations && services
				? getService(HevyOperationsService)
				: (resolvedOperations ??
					createOperations(requireClient(effectiveClient))),
		forExecution: (nextExecution) =>
			createToolRuntime({
				client: rawClient,
				baseClient: rawClient,
				operations: resolvedOperations ?? undefined,
				catalog,
				logger,
				createHandler,
				observer,
				execution: (() => {
					const nested: {
						-readonly [
							K in keyof ToolExecutionContext
						]?: ToolExecutionContext[K];
					} = {};
					if (nextExecution) Object.assign(nested, nextExecution);
					nested.signal = mergeAbortSignals(
						lifecycleSignal,
						nextExecution?.signal,
					);
					nested.deadline =
						nextExecution?.deadline ??
						effectiveExecutionDeadline ??
						Date.now() + executionTimeoutMs;
					return nested as ToolExecutionContext;
				})(),
				executionTimeoutMs,
				executionDeadline:
					nextExecution?.deadline ?? effectiveExecutionDeadline,
				lifecycleSignal,
			}),
	};
	return runtime;
}

export { HEVY_CLIENT_NOT_INITIALIZED_ERROR };

import type { McpServer, ToolAnnotations } from "@modelcontextprotocol/server";
import { Effect } from "effect";
import { z } from "zod";
import { respond, type ResponseContract } from "../utils/response-contracts.js";
import { compactJsonSchema } from "../utils/compact-json-schema.js";
import type { InferToolParams } from "../utils/tool-helpers.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import type { ToolRuntime } from "./tool-runtime.js";
import type { ToolExecutionContext } from "../execution.js";

type ToolDefinitionBase<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: TSchema;
	readonly annotations: ToolAnnotations;
	readonly responseContract: ResponseContract<TResult>;
	execute(
		runtime: ToolRuntime,
		args: InferToolParams<TSchema>,
	): Effect.Effect<TResult, unknown, never>;
};

type RegisteredToolConfig = {
	description: string;
	inputSchema: ReturnType<typeof compactJsonSchema>;
	annotations: ToolAnnotations;
	outputSchema?: ReturnType<typeof compactJsonSchema>;
};

export type ToolRegistrar = Pick<McpServer, "registerTool">;

export type ToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = ToolDefinitionBase<TSchema, TResult> &
	(
		| {
				readonly kind: "read";
				readonly outputSchema: z.ZodRawShape;
		  }
		| {
				readonly kind: "write";
				readonly outputSchema?: z.ZodRawShape;
		  }
	);

type AnyToolDefinition = ToolDefinition<Record<string, z.ZodTypeAny>, unknown>;

/**
 * One-time-per-isolate registration metadata for each tool definition.
 *
 * Building a tool's compact JSON Schema (and the SDK's eager wire conversion
 * of the `compactJsonSchema`-wrapped schema on registration) is the dominant
 * CPU cost when constructing an MCP server. Tool definitions are module-level
 * constants, so this metadata can be computed once and shared by every server
 * a single isolate builds. The SDK's `registerTool` reads the schema strictly
 * through the Standard Schema interface and never mutates it, so sharing the
 * memoized config across concurrent servers is safe.
 *
 * Keep the memo lazy: CLI and test processes that never build a Hevy server
 * pay nothing. Isolate-based edge runtimes that want the one-time conversion
 * moved into module-scope (outside request CPU) call `preloadHevyToolSchemas`.
 */
const registeredToolConfigCache = new WeakMap<
	AnyToolDefinition,
	RegisteredToolConfig
>();

export function getRegisteredToolConfig(
	definition: AnyToolDefinition,
): RegisteredToolConfig {
	const cached = registeredToolConfigCache.get(definition);
	if (cached) return cached;
	const config: RegisteredToolConfig = {
		description: definition.description,
		inputSchema: compactJsonSchema(z.strictObject(definition.inputSchema)),
		annotations: definition.annotations,
	};
	if (definition.outputSchema) {
		config.outputSchema = compactJsonSchema(z.object(definition.outputSchema));
	}
	registeredToolConfigCache.set(definition, config);
	return config;
}

export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: AnyToolDefinition,
): void {
	const directHandler = (
		args: InferToolParams<typeof definition.inputSchema>,
		requestContext?: ToolExecutionContext,
	) =>
		Effect.suspend(() => {
			const scopedRuntime = requestContext
				? runtime.forExecution(requestContext)
				: runtime;
			return definition
				.execute(scopedRuntime, args)
				.pipe(Effect.map((data) => respond(definition.responseContract, data)));
		});
	const handler = runtime.createHandler(directHandler, definition.name, {
		feature: definition.feature,
		kind: definition.kind,
		operation: definition.operation,
	});

	const config = getRegisteredToolConfig(definition);
	server.registerTool(definition.name, config, (args, context) =>
		handler(
			z.strictObject(definition.inputSchema).parse(args),
			context
				? {
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					}
				: undefined,
		),
	);
}

import { preloadCompactJsonSchema } from "../utils/compact-json-schema.js";
import {
	getRegisteredToolConfig,
	registerToolDefinition,
	type ToolRegistrar,
} from "./define-tool.js";
import { bodyMeasurementToolDefinitions } from "./body-measurements.js";
import { folderToolDefinitions } from "./folders.js";
import { routineToolDefinitions } from "./routines.js";
import { templateToolDefinitions } from "./templates.js";
import { routineDiscoveryToolDefinitions } from "./routine-discovery.js";
import { workflowToolDefinitions } from "./workflows.js";
import { workoutToolDefinitions } from "./workouts.js";
import type { ToolRuntime } from "./tool-runtime.js";

export const hevyToolDefinitions = [
	...workoutToolDefinitions,
	...routineToolDefinitions,
	...templateToolDefinitions,
	...folderToolDefinitions,
	...bodyMeasurementToolDefinitions,
	...workflowToolDefinitions,
	...routineDiscoveryToolDefinitions,
] as const;

/**
 * Move the one-time tool schema conversion into module scope.
 *
 * Tool schemas are module-level constants, and their compact JSON Schema is
 * memoized per definition by `getRegisteredToolConfig`. Populating the memo is
 * not enough: `compactJsonSchema` stores the actual `z.toJSONSchema` work
 * behind lazy `input`/`output` closures, and the MCP SDK invokes those during
 * `registerTool`. This forces the exact conversions the SDK consumes (`input`
 * for each `inputSchema`, `output` for each read tool `outputSchema`) so a
 * first request only reads already-converted schemas.
 *
 * On isolate-based edge runtimes (Cloudflare Workers) module-scope work runs
 * during isolate warm-up, outside a request's billed CPU, so calling this at
 * module scope keeps the first request of a fresh isolate fast. Idempotent,
 * and a no-op after every conversion has been computed once.
 */
export function preloadHevyToolSchemas(): void {
	for (const definition of hevyToolDefinitions) {
		const config = getRegisteredToolConfig(definition);
		preloadCompactJsonSchema(config.inputSchema, "input");
		if (config.outputSchema) {
			preloadCompactJsonSchema(config.outputSchema, "output");
		}
	}
}

/** Register every Hevy tool in its production ordering. */
export function registerHevyTools(
	server: ToolRegistrar,
	runtime: ToolRuntime,
): void {
	for (const definition of hevyToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
}

import { Effect } from "effect";

type EffectOperation<TArgs extends readonly unknown[], TResult> = {
	readonly effect: (...args: TArgs) => Effect.Effect<TResult, unknown, never>;
};

export function requireOperation<T>(operation: T | undefined, id: string): T {
	if (operation === undefined) {
		throw new Error(`Operation ${id} is unavailable.`);
	}
	return operation;
}

export function operationEffect<TArgs extends readonly unknown[], TResult>(
	operation: EffectOperation<TArgs, TResult>,
	...args: TArgs
): Effect.Effect<TResult, unknown, never> {
	return Effect.suspend(() => operation.effect(...args));
}

import {
	diagnosticEndpointIdentity,
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
	isHevyHttpError,
	ApiError,
	NetworkError,
	NotFoundError,
	RateLimitError,
	ValidationError,
} from "@hevy-mcp/hevy-client";
import {
	isBoolean,
	isFiniteNumber,
	isFunction,
	isObject,
	isString,
} from "./type-predicates.js";
import type { RuntimeValue } from "./type-predicates.js";
import { SafeUserError } from "./safe-user-error.js";
import type {
	HevyCommitState,
	HevyExecutionOutcome,
	HevyOperationSafety,
	HevyRequestPhase,
} from "@hevy-mcp/hevy-client";

/** Specific error types for categorization and metrics. */
export enum ErrorType {
	API_ERROR = "API_ERROR",
	RATE_LIMIT = "RATE_LIMIT",
	VALIDATION_ERROR = "VALIDATION_ERROR",
	NOT_FOUND = "NOT_FOUND",
	NETWORK_ERROR = "NETWORK_ERROR",
	UNKNOWN_ERROR = "UNKNOWN_ERROR",
}

type HeaderValue = string | number | string[] | undefined;
type HeaderMap = { [key: string]: HeaderValue };

export type SafeErrorCategory =
	| "AggregateError"
	| "DOMException"
	| "Error"
	| "EvalError"
	| "HevyHttpError"
	| "RangeError"
	| "ReferenceError"
	| "SyntaxError"
	| "TypeError"
	| "URIError"
	| "UnknownError";

export interface SafeStackFrame {
	source: SafeSourceId;
	line: number;
	column: number;
}

export interface SafeErrorDiagnostic {
	category: SafeErrorCategory;
	code?: string;
	status?: number;
	method?: string;
	endpoint?: string;
	frames?: SafeStackFrame[];
	phase?: HevyRequestPhase;
	operation_safety?: HevyOperationSafety;
	commit_state?: HevyCommitState;
	safe_to_retry?: boolean;
	outcome?: HevyExecutionOutcome;
}

type SafeSourceId =
	| "error-handler"
	| "hevy-client"
	| "index"
	| "server"
	| "worker";

/** Categories createSafeErrorDiagnostic may emit; part of the module's interface. */
export const SAFE_ERROR_CATEGORIES: ReadonlySet<SafeErrorCategory> =
	Object.freeze(
		new Set<SafeErrorCategory>([
			"AggregateError",
			"DOMException",
			"Error",
			"EvalError",
			"HevyHttpError",
			"RangeError",
			"ReferenceError",
			"SyntaxError",
			"TypeError",
			"URIError",
			"UnknownError",
		]),
	);

type RetryAwareError = {
	hevyRetryCount?: number;
	hevyRetryExhausted?: boolean;
	retryCount?: number;
	retryExhausted?: boolean;
};

type TaggedHttpError =
	| ApiError
	| NotFoundError
	| RateLimitError
	| ValidationError;
type TaggedClientError = TaggedHttpError | NetworkError;

function isTaggedClientError(error: RuntimeValue): error is TaggedClientError {
	return (
		error instanceof ApiError ||
		error instanceof NetworkError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError
	);
}

function isTaggedHttpError(error: RuntimeValue): error is TaggedHttpError {
	return (
		error instanceof ApiError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError
	);
}

const ABORT_TIMEOUT_METADATA = {
	AbortError: {
		code: HEVY_REQUEST_ABORTED_ERROR_CODE,
		outcome: "cancelled" as const,
	},
	TimeoutError: {
		code: HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
		outcome: "deadline_exceeded" as const,
	},
} as const;

type AbortTimeoutErrorMetadata =
	(typeof ABORT_TIMEOUT_METADATA)[keyof typeof ABORT_TIMEOUT_METADATA] & {
		name: keyof typeof ABORT_TIMEOUT_METADATA;
	};

/** Map raw cancellation errors to their bounded execution metadata. */
function getAbortTimeoutErrorMetadata(
	error: RuntimeValue,
): AbortTimeoutErrorMetadata | undefined {
	try {
		if (!(error instanceof Error)) return undefined;
		const name = error.name as keyof typeof ABORT_TIMEOUT_METADATA;
		const metadata = ABORT_TIMEOUT_METADATA[name];
		return metadata ? { name, ...metadata } : undefined;
	} catch {
		return undefined;
	}
}

/** Bounded error codes diagnostics may carry; adapters validate against this. */
export const SAFE_ERROR_CODES: ReadonlySet<string> = Object.freeze(
	new Set([
		"EAI_AGAIN",
		"ECONNABORTED",
		"ECONNREFUSED",
		"ECONNRESET",
		"ENETUNREACH",
		"ENOTFOUND",
		"ERR_NETWORK",
		"ERR_SOCKET_TIMEOUT",
		"ETIMEDOUT",
		"HEVY_INVALID_ENDPOINT",
		HEVY_REQUEST_ABORTED_ERROR_CODE,
		HEVY_RETRY_EXHAUSTED_ERROR_CODE,
		HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
	]),
);

/** Bounded HTTP methods diagnostics may carry. */
export const SAFE_HTTP_METHODS: ReadonlySet<string> = Object.freeze(
	new Set(["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]),
);

const SAFE_SOURCE_SUFFIXES: ReadonlyArray<readonly [string, SafeSourceId]> = [
	["/packages/core/src/utils/error-handler.ts", "error-handler"],
	["/packages/hevy-client/src/hevy-client-kubb.ts", "hevy-client"],
	["/packages/node/src/index.ts", "index"],
	["/packages/core/src/server.ts", "server"],
	["/packages/worker/src/worker.ts", "worker"],
];

const PROJECT_PATH_MARKER = "/hevy-mcp/";

/** Stack-frame sources diagnostics may name; adapters validate against this. */
export const SAFE_STACK_SOURCES: ReadonlySet<SafeSourceId> = Object.freeze(
	new Set(SAFE_SOURCE_SUFFIXES.map(([, id]) => id)),
);
const MAX_STACK_POSITION = 1_000_000;

function normalizeHeaderValue(value: RuntimeValue): string | undefined {
	if (isString(value)) {
		const trimmed = value.trim();
		return trimmed.length > 0 ? trimmed : undefined;
	}

	if (isFiniteNumber(value)) {
		return String(value);
	}

	if (Array.isArray(value) && value.length > 0) {
		return normalizeHeaderValue(value[0]);
	}

	return undefined;
}

function getHeaderValue(
	headers: RuntimeValue,
	key: string,
): string | undefined {
	try {
		if (!isObject(headers)) return undefined;

		if ("get" in headers && isFunction((headers as { get?: unknown }).get)) {
			const value = (headers as { get: (headerName: string) => unknown }).get(
				key,
			);
			return normalizeHeaderValue(value);
		}

		const headerRecord = headers as HeaderMap;
		return normalizeHeaderValue(
			headerRecord[key] ??
				headerRecord[key.toLowerCase()] ??
				headerRecord[key.toUpperCase()],
		);
	} catch {
		return undefined;
	}
}

/** Extract a valid HTTP status without retaining untrusted error metadata. */
export function extractErrorStatus(error: RuntimeValue): number | undefined {
	try {
		const status = isHevyHttpError(error)
			? error.status
			: isTaggedHttpError(error)
				? error.status
				: undefined;
		return status !== undefined &&
			Number.isInteger(status) &&
			status >= 100 &&
			status <= 599
			? status
			: undefined;
	} catch {
		return undefined;
	}
}

/** Return whether the client exhausted its bounded transient retry policy. */
export function isRetryExhausted(error: RuntimeValue): boolean {
	try {
		return (
			!!error &&
			isObject(error) &&
			((error as RetryAwareError).hevyRetryExhausted === true ||
				(error as RetryAwareError).retryExhausted === true)
		);
	} catch {
		return false;
	}
}

/** Interpret a Retry-After header as seconds from the supplied current time. */
export function getRetryAfterSeconds(
	error: RuntimeValue,
	now = Date.now(),
): number | undefined {
	try {
		if (error instanceof RateLimitError) return error.retryAfterSeconds;
		if (!isHevyHttpError(error)) return undefined;
		const retryAfterHeader = getHeaderValue(error.headers, "retry-after");
		if (!retryAfterHeader) return undefined;

		const seconds = Number(retryAfterHeader);
		if (Number.isFinite(seconds) && seconds >= 0) return seconds;

		const retryAtMillis = Date.parse(retryAfterHeader);
		if (Number.isNaN(retryAtMillis)) return undefined;
		return Math.ceil(Math.max(0, retryAtMillis - now) / 1000);
	} catch {
		return undefined;
	}
}

/** Map bounded Hevy HTTP statuses to stable user-facing messages. */
export function getStatusErrorMessage(
	status?: number,
	method?: string,
	endpoint?: string,
): string | null {
	if (
		status === 404 &&
		method?.toUpperCase() === "PUT" &&
		endpoint === "/v1/routines/:routineId"
	) {
		return "The requested routine was not found in Hevy. It may have been deleted or the routine ID is incorrect.";
	}
	if (status === 400 || status === 422) {
		return "The request failed Hevy validation. Check the field values and try again.";
	}
	if (status === 401 || status === 403) {
		return "The Hevy API key is invalid or has expired. Check HEVY_API_KEY.";
	}
	if (status === 404) return "The requested resource was not found in Hevy.";
	if (
		status === 409 &&
		method?.toUpperCase() === "POST" &&
		endpoint === "/v1/body_measurements"
	) {
		return "A body measurement already exists for this date. Use the update-body-measurement tool to modify it.";
	}
	if (status === 409) {
		return "A conflict occurred because the resource already exists or conflicts with the current server state. Check whether it already exists and use the update tool when appropriate.";
	}
	if (status === 429) return "Rate limited by Hevy. Please wait and retry.";
	if (status !== undefined && status >= 500 && status <= 599) {
		return "Hevy API experienced an error. Please retry later.";
	}
	return null;
}

function formatSecondsLabel(seconds: number): string {
	const roundedSeconds = Math.max(0, Math.round(seconds));
	const suffix = roundedSeconds === 1 ? "" : "s";
	return `${roundedSeconds} second${suffix}`;
}

function getRateLimitMessage(error: RuntimeValue): string {
	const seconds = getRetryAfterSeconds(error);
	if (seconds !== undefined) {
		return `Rate limited by Hevy (HTTP 429). Please wait about ${formatSecondsLabel(seconds)} before retrying.`;
	}
	return "Rate limited by Hevy (HTTP 429). Please wait and retry your request.";
}

function getRetryExhaustedMessage(error: RuntimeValue): string {
	let retryCount: unknown;
	try {
		retryCount = isObject(error)
			? ((error as RetryAwareError).hevyRetryCount ??
				(error as RetryAwareError).retryCount)
			: undefined;
	} catch {
		retryCount = undefined;
	}
	const attemptCount = isFiniteNumber(retryCount) ? retryCount + 1 : undefined;
	if (attemptCount) {
		return `Unable to complete the request after ${attemptCount} attempts to the Hevy API due to transient failures. Please try again shortly.`;
	}
	return "Unable to complete the request after multiple attempts to the Hevy API due to transient failures. Please try again shortly.";
}

const MAX_SAFE_USER_ERROR_LENGTH = 512;

/** Classify an error using bounded status, names, and supplied text. */
export function determineErrorType(
	error: RuntimeValue,
	message: string,
): ErrorType {
	if (error instanceof RateLimitError) return ErrorType.RATE_LIMIT;
	if (error instanceof ValidationError) return ErrorType.VALIDATION_ERROR;
	if (error instanceof NotFoundError) return ErrorType.NOT_FOUND;
	if (error instanceof ApiError) return ErrorType.API_ERROR;
	if (error instanceof NetworkError) return ErrorType.NETWORK_ERROR;
	if (isRetryExhausted(error)) return ErrorType.NETWORK_ERROR;
	if (extractErrorStatus(error) === 429) return ErrorType.RATE_LIMIT;

	let originalMessage = "";
	let nameLower = "";
	try {
		if (error instanceof Error) {
			originalMessage = error.message.slice(0, 512);
			nameLower = error.name.toLowerCase();
		}
	} catch {
		originalMessage = "";
		nameLower = "";
	}
	const classificationText = `${message}\n${originalMessage}`.toLowerCase();

	if (
		nameLower.includes("network") ||
		classificationText.includes("network") ||
		classificationText.includes("fetch") ||
		classificationText.includes("timeout")
	) {
		return ErrorType.NETWORK_ERROR;
	}
	if (
		nameLower.includes("validation") ||
		classificationText.includes("validation") ||
		classificationText.includes("invalid") ||
		classificationText.includes("required")
	) {
		return ErrorType.VALIDATION_ERROR;
	}
	if (
		classificationText.includes("not found") ||
		classificationText.includes("404") ||
		classificationText.includes("does not exist")
	) {
		return ErrorType.NOT_FOUND;
	}
	if (
		nameLower.includes("api") ||
		classificationText.includes("api") ||
		classificationText.includes("server error") ||
		classificationText.includes("500")
	) {
		return ErrorType.API_ERROR;
	}
	return ErrorType.UNKNOWN_ERROR;
}

function classifyError(error: RuntimeValue): SafeErrorCategory {
	if (isHevyHttpError(error)) return "HevyHttpError";
	if (error instanceof TypeError) return "TypeError";
	if (error instanceof RangeError) return "RangeError";
	if (error instanceof ReferenceError) return "ReferenceError";
	if (error instanceof SyntaxError) return "SyntaxError";
	if (error instanceof URIError) return "URIError";
	if (error instanceof EvalError) return "EvalError";
	if (error instanceof AggregateError) return "AggregateError";
	if (error instanceof DOMException) {
		return "DOMException";
	}
	if (error instanceof Error) return "Error";
	return "UnknownError";
}

function getSafeCode(error: RuntimeValue): string | undefined {
	const abortTimeout = getAbortTimeoutErrorMetadata(error);
	if (abortTimeout) return abortTimeout.code;
	if (!isObject(error) || !("code" in error)) {
		return undefined;
	}
	const code = error.code;
	return isString(code) && SAFE_ERROR_CODES.has(code) ? code : undefined;
}

function getSafeMethod(error: RuntimeValue): string | undefined {
	if (!isHevyHttpError(error) && !isTaggedHttpError(error)) return undefined;
	if (!isObject(error) || !("method" in error) || !isString(error.method))
		return undefined;
	const method = error.method.toUpperCase();
	return SAFE_HTTP_METHODS.has(method) ? method : undefined;
}

function getSafeEndpoint(error: RuntimeValue): string | undefined {
	if (!isHevyHttpError(error) && !isTaggedHttpError(error)) return undefined;
	if (!isObject(error) || !("endpoint" in error) || !isString(error.endpoint))
		return undefined;
	return diagnosticEndpointIdentity(error.endpoint);
}

function getExecutionFields(
	error: RuntimeValue,
): Pick<
	SafeErrorDiagnostic,
	"phase" | "operation_safety" | "commit_state" | "safe_to_retry" | "outcome"
> {
	if (!isHevyHttpError(error) && !isTaggedClientError(error)) {
		const abortTimeout = getAbortTimeoutErrorMetadata(error);
		if (abortTimeout) {
			return {
				commit_state: "unknown",
				safe_to_retry: false,
				outcome: abortTimeout.outcome,
			};
		}
		return {};
	}
	if (isTaggedClientError(error)) {
		return {
			phase: error.phase,
			operation_safety: error.operationSafety,
			commit_state: error.commitState,
			safe_to_retry: error.safeToRetry,
			outcome: error.outcome,
		};
	}
	if (!isHevyHttpError(error)) return {};
	const fields: Partial<
		Pick<
			SafeErrorDiagnostic,
			| "phase"
			| "operation_safety"
			| "commit_state"
			| "safe_to_retry"
			| "outcome"
		>
	> = {};
	if (error.phase) fields.phase = error.phase;
	if (error.operation_safety) fields.operation_safety = error.operation_safety;
	if (error.commit_state) fields.commit_state = error.commit_state;
	if (isBoolean(error.safe_to_retry))
		fields.safe_to_retry = error.safe_to_retry;
	if (error.outcome) fields.outcome = error.outcome;
	return fields;
}

function parseSafeStackFrames(
	error: RuntimeValue,
): SafeStackFrame[] | undefined {
	if (!(error instanceof Error) || !isString(error.stack)) {
		return undefined;
	}

	const frames: SafeStackFrame[] = [];
	for (const frameLine of error.stack.split(/\r?\n/).slice(1)) {
		const match =
			/^\s{4}at (?:[^()\r\n]+ \()?([^()\s\r\n]+):(\d+):(\d+)\)?$/.exec(
				frameLine,
			);
		if (!match) continue;
		const [, rawSource, rawLine, rawColumn] = match;
		if (!rawSource || !rawLine || !rawColumn) continue;
		if (
			rawSource.includes("?") ||
			rawSource.includes("#") ||
			(!rawSource.startsWith("/") && !rawSource.startsWith("file:///")) ||
			!rawSource.includes(PROJECT_PATH_MARKER)
		) {
			continue;
		}
		const source = SAFE_SOURCE_SUFFIXES.find(([suffix]) =>
			rawSource.endsWith(suffix),
		)?.[1];
		if (!source) continue;
		const line = Number(rawLine);
		const column = Number(rawColumn);
		if (
			!Number.isSafeInteger(line) ||
			!Number.isSafeInteger(column) ||
			line < 1 ||
			column < 1 ||
			line > MAX_STACK_POSITION ||
			column > MAX_STACK_POSITION
		) {
			continue;
		}
		frames.push({ source, line, column });
		if (frames.length === 3) break;
	}
	return frames.length > 0 ? frames : undefined;
}

/** Build bounded diagnostic metadata with no raw messages, payloads, or URLs. */
export function createSafeErrorDiagnostic(
	error: RuntimeValue,
): SafeErrorDiagnostic {
	try {
		const diagnostic: SafeErrorDiagnostic = { category: classifyError(error) };
		const code = getSafeCode(error);
		const status = extractErrorStatus(error);
		const method = getSafeMethod(error);
		const endpoint = getSafeEndpoint(error);
		const frames = parseSafeStackFrames(error);
		if (code) diagnostic.code = code;
		if (status !== undefined) diagnostic.status = status;
		if (method) diagnostic.method = method;
		if (endpoint) diagnostic.endpoint = endpoint;
		if (frames) diagnostic.frames = frames;
		Object.assign(diagnostic, getExecutionFields(error));
		return diagnostic;
	} catch {
		return { category: "UnknownError" };
	}
}

export interface ErrorPolicyResult {
	type: ErrorType;
	message: string;
	diagnostic: SafeErrorDiagnostic;
}

/** Resolve all bounded policy outputs used by MCP, telemetry, and reporting adapters. */
export function resolveErrorPolicy(
	error: RuntimeValue,
	defaultMessage: string,
	notInitializedMessage?: string,
): ErrorPolicyResult {
	const diagnostic = createSafeErrorDiagnostic(error);
	const mappedMessage = getStatusErrorMessage(
		diagnostic.status,
		diagnostic.method,
		diagnostic.endpoint,
	);
	let message =
		mappedMessage ??
		(diagnostic.status !== undefined
			? `Hevy API request failed (HTTP ${diagnostic.status}).`
			: defaultMessage);
	let isNotInitialized = false;
	try {
		isNotInitialized =
			Boolean(notInitializedMessage) &&
			error instanceof Error &&
			error.message === notInitializedMessage;
	} catch {
		isNotInitialized = false;
	}
	if (isNotInitialized) {
		message = notInitializedMessage ?? defaultMessage;
	} else if (diagnostic.status === 400) {
		const responseError = isHevyHttpError(error)
			? error.responseError
			: error instanceof ValidationError
				? error.responseError
				: undefined;
		if (responseError) message = `${message} Detail: ${responseError}`;
	} else if (diagnostic.code === HEVY_REQUEST_ABORTED_ERROR_CODE) {
		// This code is emitted only for caller cancellation. Keep its explicit
		// client-facing message instead of falling back to the generic error text.
		message = "The request was canceled by the client.";
	} else if (isRetryExhausted(error)) {
		message = getRetryExhaustedMessage(error);
	} else if (diagnostic.status === 429) {
		message = getRateLimitMessage(error);
	} else if (
		diagnostic.status === undefined &&
		error instanceof SafeUserError &&
		error.message &&
		error.message !== notInitializedMessage
	) {
		message = error.message.slice(0, MAX_SAFE_USER_ERROR_LENGTH);
	}
	return { type: determineErrorType(error, message), message, diagnostic };
}

/**
 * Centralized error handling utility for MCP tools
 */

import { ErrorType, resolveErrorPolicy } from "./error-policy.js";
import type { JSONObject } from "@modelcontextprotocol/server";
import type { McpToolResponse } from "./response-contracts.js";
import { HEVY_CLIENT_NOT_INITIALIZED_ERROR } from "./tool-helpers.js";
import {
	createExecutionProjection,
	type StructuredExecutionProjection,
	type ToolExecutionContext,
} from "../execution.js";
import { createSafeErrorDiagnostic } from "./error-policy.js";
import type { RuntimeValue } from "./type-predicates.js";

export { ErrorType } from "./error-policy.js";
export type { StructuredExecutionError } from "../execution.js";

/**
 * Standard error response interface
 */
export interface ErrorResponse {
	message: string;
	code?: string;
	details?: unknown;
}

/**
 * Enhanced error response with type categorization
 */
export interface EnhancedErrorResponse extends ErrorResponse {
	type: ErrorType;
}

/** Build the canonical execution projection for an arbitrary thrown value. */
export function createExecutionErrorProjection(
	error: RuntimeValue,
): StructuredExecutionProjection {
	return createExecutionProjection(createSafeErrorDiagnostic(error));
}

export interface McpToolFailureEvent {
	readonly event: "mcp.tool.failure";
	readonly "mcp.tool.name": string;
	readonly "error.type": ErrorType;
	readonly "error.category": string;
	readonly "error.code"?: string;
	readonly "http.status_code"?: number;
	readonly "http.method"?: string;
	readonly "hevy.api.endpoint"?: string;
	readonly "hevy.api.outcome"?: StructuredExecutionProjection["outcome"];
	readonly "hevy.api.phase"?: StructuredExecutionProjection["phase"];
	readonly "hevy.api.operation_safety"?: StructuredExecutionProjection["operation_safety"];
	readonly "hevy.api.commit_state"?: StructuredExecutionProjection["commit_state"];
	readonly "hevy.api.safe_to_retry"?: boolean;
}

export function createMcpToolFailureEvent(
	toolName: string,
	errorType: ErrorType,
	diagnostic: {
		category: string;
		code?: string;
		status?: number;
		method?: string;
		endpoint?: string;
		execution?: StructuredExecutionProjection;
	},
): McpToolFailureEvent {
	const execution = diagnostic.execution;
	type MutableFailureEvent = {
		-readonly [K in keyof McpToolFailureEvent]: McpToolFailureEvent[K];
	};
	const event: MutableFailureEvent = {
		event: "mcp.tool.failure",
		"mcp.tool.name": toolName,
		"error.type": errorType,
		"error.category": diagnostic.category,
	};
	if (diagnostic.code) event["error.code"] = diagnostic.code;
	if (diagnostic.status !== undefined)
		event["http.status_code"] = diagnostic.status;
	if (diagnostic.method) event["http.method"] = diagnostic.method;
	if (diagnostic.endpoint) event["hevy.api.endpoint"] = diagnostic.endpoint;
	if (execution) {
		event["hevy.api.outcome"] = execution.outcome;
		event["hevy.api.phase"] = execution.phase;
		event["hevy.api.operation_safety"] = execution.operation_safety;
		event["hevy.api.commit_state"] = execution.commit_state;
		event["hevy.api.safe_to_retry"] = execution.safe_to_retry;
	}
	return event;
}

/** Structured debug context containing only bounded, safe metadata. */
export interface ErrorDebugContext {
	sourceContext?: string;
	originalErrorMessage: string;
	errorCode?: string;
	errorType: ErrorType;
	execution?: StructuredExecutionProjection;
	axios?: {
		status?: number;
		statusText?: string;
		method?: string;
		url?: string;
	};
}

/**
 * Create a standardized error response for MCP tools
 *
 * @param error - The error object or message
 * @param context - Optional context information about where the error occurred
 * @returns A formatted MCP tool response with error information
 */
export function createErrorResponse(
	error: RuntimeValue,
	context?: string,
): McpToolResponse {
	const policy = resolveErrorPolicy(
		error,
		"The request failed unexpectedly. Please try again.",
		HEVY_CLIENT_NOT_INITIALIZED_ERROR,
	);
	const { diagnostic } = policy;
	const execution = createExecutionProjection(diagnostic);
	const axiosErrorContext: ErrorDebugContext["axios"] | null =
		diagnostic.status !== undefined ||
		diagnostic.method !== undefined ||
		diagnostic.endpoint !== undefined
			? {
					status: diagnostic.status,
					method: diagnostic.method,
					url: diagnostic.endpoint,
				}
			: null;
	const errorContext: ErrorDebugContext = {
		sourceContext: context,
		originalErrorMessage: `${diagnostic.category} occurred`,
		errorCode: diagnostic.code,
		errorType: policy.type,
		execution,
		axios: axiosErrorContext ?? undefined,
	};
	const contextPrefix = context ? `[${context}] ` : "";
	const formattedMessage = `${contextPrefix}Error: ${policy.message}`;
	console.error(
		JSON.stringify(
			createMcpToolFailureEvent(context || "unknown", policy.type, {
				...diagnostic,
				execution,
			}),
		),
	);

	return {
		content: [{ type: "text" as const, text: formattedMessage }],
		isError: true,
		errorContext,
		structuredContent: { error: execution },
		errorOutcome: execution,
	};
}

/**
 * Wrap an async function with standardized error handling
 *
 * @param fn - The async function to wrap
 * @param context - Context information for error messages
 * @returns A function that catches errors and returns standardized error responses
 */
export function withErrorHandling<TParams extends object>(
	fn: (
		args: TParams,
		context?: ToolExecutionContext,
	) => Promise<McpToolResponse>,
	context: string,
	onError?: (
		error: RuntimeValue,
		context: string,
		argumentKeyCount: number,
	) => void,
): (
	args: JSONObject,
	context?: ToolExecutionContext,
) => Promise<McpToolResponse> {
	return async (rawArgs: JSONObject, requestContext?: ToolExecutionContext) => {
		const normalizedArgs = rawArgs ?? {};
		try {
			return await fn(normalizedArgs as TParams, requestContext);
		} catch (error) {
			try {
				onError?.(error, context, Object.keys(normalizedArgs).length);
			} catch {
				console.error("MCP error observer failure", {
					category: "ObserverError",
				});
			}

			return createErrorResponse(error, context);
		}
	};
}

import { extractErrorStatus } from "./error-policy.js";
import {
	expectedGet404Outcome,
	isExpectedMutation404 as isExpectedMutation404Policy,
	isHevyHttpError,
} from "@hevy-mcp/hevy-client";
import type { RuntimeValue } from "./type-predicates.js";

export type HevyReadOperation = "get" | "list";
export type Expected404Outcome = "not_found" | "end_of_list";

/** True only for a sanitized Hevy GET of a known single resource. */
export function isExpectedReadNotFound(error: RuntimeValue): boolean {
	return (
		isHevyHttpError(error) &&
		expectedGet404Outcome(
			error.endpoint,
			error.method,
			extractErrorStatus(error),
		) === "not_found"
	);
}

/** True only for an undocumented empty page after the first page. */
export function isExpectedListPageNotFound(
	error: RuntimeValue,
	page: number,
): boolean {
	return (
		page > 1 &&
		isHevyHttpError(error) &&
		expectedGet404Outcome(
			error.endpoint,
			error.method,
			extractErrorStatus(error),
			page,
		) === "end_of_list"
	);
}

/** Mutation/caller 404s remain MCP errors but do not create Sentry issues. */
export function isExpectedMutationNotFound(error: RuntimeValue): boolean {
	return (
		isHevyHttpError(error) &&
		isExpectedMutation404Policy(
			error.endpoint,
			error.method,
			extractErrorStatus(error),
		)
	);
}

export class SafeUserError extends Error {
	public readonly safeForUser = true;

	public constructor(message: string) {
		super(message);
		this.name = "SafeUserError";
	}
}

import { Cache, Effect, Option } from "effect";
import type { HevyRequestOptions } from "@hevy-mcp/hevy-client";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import type {
	CacheObservationMetadata,
	CacheObservationScope,
	CacheObservationState,
	CacheObserver,
} from "./cache.js";
import { bucketCount } from "./result-telemetry.js";

export const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
export const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
export const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;
const EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE = 100;

export type ExerciseTemplateCatalogRefreshReason =
	| "explicit-refresh"
	| "initial-load"
	| "ttl-expired";

export interface ExerciseTemplateCatalogOptions {
	refresh?: boolean;
	execution?: HevyRequestOptions;
	onRefreshed?: (
		catalog: ExerciseTemplate[],
		reason: ExerciseTemplateCatalogRefreshReason,
	) => void;
}

type TemplateListAllError = Effect.Error<
	ReturnType<TemplatesListAllOperation["effect"]>
>;

export type ExerciseTemplateCatalogCache = Cache.Cache<
	string,
	ExerciseTemplate[],
	TemplateListAllError
>;

export interface ExerciseTemplateCatalog {
	/**
	 * Effect-first catalog access for MCP resource and tool handlers.
	 *
	 * The server owns the cache passed to this catalog. Keeping this program
	 * Effect-valued lets the request handler decide where the one Promise
	 * collapse belongs.
	 */
	effect(
		options?: ExerciseTemplateCatalogOptions,
	): Effect.Effect<ExerciseTemplate[], TemplateListAllError>;
	/**
	 * Promise compatibility for callers that have not moved to the handler
	 * Effect boundary yet.
	 */
	get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
	reset(): void;
}

type CatalogOperations = {
	readonly templates?: {
		readonly listAll?: Pick<TemplatesListAllOperation, "effect">;
	};
};

function startObservation(
	observer: CacheObserver | undefined,
	state: CacheObservationState,
) {
	try {
		return observer?.start({ state });
	} catch {
		return undefined;
	}
}

function finishObservation(
	scope: CacheObservationScope | void,
	metadata?: CacheObservationMetadata,
): void {
	try {
		scope?.finish(metadata);
	} catch {
		// Cache observation is best-effort and cannot affect cache behavior.
	}
}

function notifyRefreshed(
	options: ExerciseTemplateCatalogOptions,
	catalog: ExerciseTemplate[],
	reason: ExerciseTemplateCatalogRefreshReason,
): void {
	try {
		options.onRefreshed?.(catalog, reason);
	} catch {
		// Cache callbacks are best-effort and cannot affect catalog behavior.
	}
}

function catalogPageCount(catalog: readonly ExerciseTemplate[]): number {
	const pages = (
		catalog as ExerciseTemplate[] & {
			readonly pageCount?: number;
		}
	).pageCount;
	if (pages !== undefined) return pages;
	return Math.max(
		1,
		Math.ceil(catalog.length / EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE),
	);
}

/**
 * Build the catalog facade around one server-owned Effect Cache.
 *
 * `cache` is deliberately supplied by the server rather than constructed
 * here. This keeps cache lifetime at server/process scope instead of making it
 * request-local in `createToolRuntime` or `forExecution`.
 */
export function createExerciseTemplateCatalog(
	operations: CatalogOperations,
	cache: ExerciseTemplateCatalogCache,
	cacheObserver?: CacheObserver,
): ExerciseTemplateCatalog {
	const listAll = operations.templates?.listAll;
	if (!listAll) {
		throw new Error("Exercise template list operation is unavailable.");
	}
	let hasLoadedValue = false;
	let requestGeneration = 0;

	const getCacheState = Effect.fn("core.exerciseTemplateCatalog.cacheState")(
		function* () {
			const successful = yield* Cache.getSuccess(
				cache,
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
			);
			if (Option.isSome(successful)) {
				return "hit" as const;
			}
			const present = yield* Cache.has(
				cache,
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
			);
			return present
				? ("inflight_wait" as const)
				: hasLoadedValue
					? ("expired" as const)
					: ("miss" as const);
		},
	);

	const effect = Effect.fn("core.exerciseTemplateCatalog.get")(function* (
		options: ExerciseTemplateCatalogOptions = {},
	) {
		const refresh = options.refresh === true;
		const execution = options.execution;
		const observedState = refresh ? "refresh" : yield* getCacheState();
		const state =
			execution !== undefined && observedState === "inflight_wait"
				? "miss"
				: observedState;
		const observationScope = startObservation(cacheObserver, state);
		const reason: ExerciseTemplateCatalogRefreshReason =
			state === "refresh"
				? "explicit-refresh"
				: state === "expired"
					? "ttl-expired"
					: "initial-load";
		const sharedCacheLoad = state === "hit" || state === "inflight_wait";
		const bypassCache = refresh || (execution !== undefined && state !== "hit");
		const replaceSharedCacheLoad =
			observedState === "inflight_wait" && (refresh || execution !== undefined);
		const generation = sharedCacheLoad
			? requestGeneration
			: ++requestGeneration;
		const load = bypassCache
			? replaceSharedCacheLoad
				? Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY).pipe(
						Effect.flatMap(() =>
							execution === undefined
								? listAll.effect()
								: listAll.effect(execution),
						),
					)
				: execution === undefined
					? listAll.effect()
					: listAll.effect(execution)
			: Cache.get(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY);
		const shouldNotify = !sharedCacheLoad;
		let observationMetadata: CacheObservationMetadata | undefined;

		const observedLoad = load.pipe(
			Effect.tap((catalog) =>
				Effect.gen(function* () {
					if (!sharedCacheLoad && generation === requestGeneration) {
						hasLoadedValue = true;
					}
					if (bypassCache && generation === requestGeneration) {
						yield* Cache.set(
							cache,
							EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
							catalog,
						);
					}
					if (!sharedCacheLoad) {
						observationMetadata = {
							refreshReason: reason,
							pageCountBucket: bucketCount(catalogPageCount(catalog)),
							itemCountBucket: bucketCount(catalog.length),
						};
					}
					if (shouldNotify) {
						notifyRefreshed(options, catalog, reason);
					}
				}),
			),
			Effect.catch((error) =>
				Effect.flatMap(
					generation === requestGeneration
						? Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY)
						: Effect.void,
					() => Effect.fail(error),
				),
			),
		);

		const controlledLoad = execution
			? checkExecution(execution).pipe(Effect.flatMap(() => observedLoad))
			: observedLoad;

		return yield* Effect.ensuring(
			controlledLoad,
			Effect.sync(() => {
				finishObservation(observationScope, observationMetadata);
			}),
		);
	});

	return {
		effect,
		get(options) {
			return Effect.runPromise(effect(options));
		},
		reset() {
			hasLoadedValue = false;
			requestGeneration += 1;
			Effect.runSync(
				Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY),
			);
		},
	};
}

function checkExecution(execution: HevyRequestOptions) {
	return Effect.sync(() => {
		if (execution.signal?.aborted) {
			throw (
				execution.signal.reason ??
				new DOMException("Operation canceled", "AbortError")
			);
		}
		if (execution.deadline !== undefined && Date.now() >= execution.deadline) {
			throw new DOMException("Operation deadline exceeded", "TimeoutError");
		}
	});
}

import type { ResultCountBucket } from "./result-telemetry.js";

export type CacheObservationState =
	| "hit"
	| "miss"
	| "refresh"
	| "expired"
	| "inflight_wait";

export interface CacheObservationMetadata {
	readonly refreshReason?: "explicit-refresh" | "initial-load" | "ttl-expired";
	readonly pageCountBucket?: ResultCountBucket;
	readonly itemCountBucket?: ResultCountBucket;
}

export interface CacheObservation extends CacheObservationMetadata {
	readonly state: CacheObservationState;
}

export interface CacheObservationScope {
	finish(metadata?: CacheObservationMetadata): void;
}

export interface CacheObserver {
	start(observation: CacheObservation): CacheObservationScope | void;
}

export interface AsyncCacheOptions {
	ttlMs: number;
	maxSize: number;
	observer?: CacheObserver;
}

export interface CacheGetOptions {
	refresh?: boolean;
	/** Controlled callers must not share an in-flight request they can cancel. */
	shareInFlight?: boolean;
	signal?: AbortSignal;
	deadline?: number;
	getObservationMetadata?: () => CacheObservationMetadata | undefined;
}

