export type SafeToolArgumentKey =
	| "date"
	| "end_date"
	| "exercise_template_id"
	| "folder_id"
	| "include_custom"
	| "limit"
	| "offset"
	| "page"
	| "page_size"
	| "primary_muscle_group"
	| "query"
	| "refresh"
	| "routine_id"
	| "since"
	| "start_date"
	| "updated_since"
	| "workout_id";

export type SafeToolPresenceArgumentKey = Extract<
	SafeToolArgumentKey,
	| "date"
	| "end_date"
	| "exercise_template_id"
	| "folder_id"
	| "primary_muscle_group"
	| "query"
	| "routine_id"
	| "since"
	| "start_date"
	| "updated_since"
	| "workout_id"
>;

export type SafeToolNumericArgumentKey = Extract<
	SafeToolArgumentKey,
	"limit" | "offset" | "page" | "page_size"
>;

export type SafeToolBooleanArgumentKey = Extract<
	SafeToolArgumentKey,
	"include_custom" | "refresh"
>;

export interface ToolInvocationObservation {
	readonly name: string;
	/** The MCP primitive being observed; omitted values remain tool-compatible. */
	readonly kind?: "tool" | "prompt";
	readonly taxonomy?: ToolTelemetryMetadata;
	readonly argumentKeys?: readonly SafeToolArgumentKey[];
	readonly argumentPresence?: Partial<
		Readonly<Record<SafeToolPresenceArgumentKey, true>>
	>;
	readonly numericArgumentBuckets?: Partial<
		Readonly<Record<SafeToolNumericArgumentKey, ResultCountBucket>>
	>;
	readonly booleanArguments?: Partial<
		Readonly<Record<SafeToolBooleanArgumentKey, boolean>>
	>;
	readonly argumentKeyCountBucket?: ResultCountBucket;
}

export interface ToolResultObservation {
	readonly isError: boolean;
	readonly hasStructuredContent: boolean;
	readonly contentCountBucket: ResultCountBucket;
	readonly summary?: ToolResultTelemetry;
}

export interface ToolCompletionObservation {
	readonly outcome: "success" | "returned_error" | "thrown_error";
	readonly durationMs: number;
	readonly result?: ToolResultObservation;
	readonly errorType?: ErrorType;
	readonly error?: SafeErrorDiagnostic;
	readonly errorOutcome?: StructuredExecutionProjection;
}

export interface ToolObservationScope {
	run<T>(operation: () => Promise<T>): Promise<T>;
	finish(completion: ToolCompletionObservation): void | Promise<void>;
}

export interface ToolObserver {
	start(invocation: ToolInvocationObservation): ToolObservationScope | void;
}

export type SafeToolInvocation = ToolInvocationObservation;
export type SafeToolCompletion = ToolCompletionObservation;

export function memoizeObservationScope(
	scope: ToolObservationScope | void,
): ToolObservationScope | undefined {
	if (!scope) return undefined;
	let finished = false;
	let operationPromise: Promise<unknown> | undefined;
	return {
		run<T>(operation: () => Promise<T>): Promise<T> {
			if (!operationPromise) {
				try {
					operationPromise = Promise.resolve(scope.run(operation));
				} catch (error) {
					operationPromise = Promise.reject(error);
				}
			}
			return operationPromise as Promise<T>;
		},
		finish(completion) {
			if (finished) return;
			finished = true;
			try {
				const pending = scope.finish(completion);
				if (pending) void pending.catch(() => undefined);
			} catch {
				// Observation must never alter MCP behavior.
			}
		},
	};
}

import type { LoggingMessageNotification } from "@modelcontextprotocol/server";
import { createSafeErrorDiagnostic } from "./error-policy.js";
import type { RuntimeValue } from "./type-predicates.js";

export type McpClientLogMessage = LoggingMessageNotification["params"];
export type McpClientLogger = (message: McpClientLogMessage) => void;

interface LoggingServer {
	isConnected(): boolean;
	sendLoggingMessage(message: McpClientLogMessage): Promise<void>;
}

const SEND_FAILURE_MESSAGE =
	"Failed to send structured log message to MCP client";
const DISCONNECTED_MESSAGE =
	"Skipped structured MCP client log because the server is not connected";

/**
 * Create a best-effort, fire-and-forget logger for an MCP server connection.
 * Logging failures are reported to stderr and never escape into tool behavior.
 */
export function createMcpClientLogger(server: LoggingServer): McpClientLogger {
	return (message) => {
		try {
			if (!server.isConnected()) {
				console.error(DISCONNECTED_MESSAGE);
				return;
			}

			void server.sendLoggingMessage(message).catch((error: RuntimeValue) => {
				console.error(SEND_FAILURE_MESSAGE, createSafeErrorDiagnostic(error));
			});
		} catch (error) {
			console.error(SEND_FAILURE_MESSAGE, createSafeErrorDiagnostic(error));
		}
	};
}

import { describe, expect, it, vi } from "vitest";
import { Context, Effect, Layer, Option } from "effect";
import {
	ExerciseTemplateCatalogService,
	HevyClientService,
	HevyOperationsService,
	ToolExecutionContextService,
	ToolObserverService,
} from "../effect-services.js";
import { createMockHevyClient } from "../../test-fixtures/mock-hevy.js";
import {
	createToolRuntime,
	HEVY_CLIENT_NOT_INITIALIZED_ERROR,
	type ToolHandler,
	type ToolHandlerFactory,
} from "./tool-runtime.js";
import type { McpToolResponse } from "../utils/response-contracts.js";
import { createOperations } from "@hevy-mcp/operations";

const runImmediately = <T>(operation: () => Promise<T>): Promise<T> =>
	operation();

const catalog = {
	effect: () => Effect.succeed([]),
	get: () => Promise.resolve([]),
	reset: () => undefined,
};

function resolveRuntimeServices(runtime: ReturnType<typeof createToolRuntime>) {
	if (!runtime.layer) {
		throw new Error("Expected runtime to provide a service layer");
	}
	return Effect.runSync(Effect.scoped(Layer.build(runtime.layer)));
}

describe("createToolRuntime service layer", () => {
	it("throws the canonical not-initialized error for client service lookup without a client", () => {
		const runtime = createToolRuntime({
			client: null,
			operations: createOperations(createMockHevyClient()),
			catalog,
		});

		expect(() => runtime.service(HevyClientService)).toThrowError(
			HEVY_CLIENT_NOT_INITIALIZED_ERROR,
		);
		expect(() => runtime.getClient()).toThrowError(
			HEVY_CLIENT_NOT_INITIALIZED_ERROR,
		);
	});

	it("provides core services from the objects passed to the runtime", () => {
		const client = createMockHevyClient();
		const operations = createOperations(client);
		const execution = {
			requestId: "request-1",
			deadline: 123,
		};
		const runtime = createToolRuntime({
			client,
			operations,
			catalog,
			execution,
		});
		const services = resolveRuntimeServices(runtime);

		expect(Context.get(services, HevyClientService)).toBe(runtime.getClient());
		expect(Context.get(services, HevyOperationsService)).toBe(operations);
		expect(Context.get(services, ExerciseTemplateCatalogService)).toBe(
			runtime.catalog,
		);
		expect(Context.get(services, ToolExecutionContextService)).toBe(execution);
		expect(runtime.getClient()).toBe(Context.get(services, HevyClientService));
		expect(runtime.service(HevyClientService)).toBe(runtime.getClient());
		expect(runtime.getOperations()).toBe(
			Context.get(services, HevyOperationsService),
		);
		expect(runtime.service(HevyOperationsService)).toBe(
			runtime.getOperations(),
		);
	});

	it("composes the observer service only when an observer is configured", () => {
		const withObserver = { start: vi.fn() };
		const observedRuntime = createToolRuntime({
			client: createMockHevyClient(),
			catalog,
			observer: withObserver,
		});
		const observedServices = resolveRuntimeServices(observedRuntime);
		expect(Context.get(observedServices, ToolObserverService)).toBe(
			withObserver,
		);

		const unobservedRuntime = createToolRuntime({
			client: createMockHevyClient(),
			catalog,
		});
		const unobservedServices = resolveRuntimeServices(unobservedRuntime);
		expect(Context.getOption(unobservedServices, ToolObserverService)).toBe(
			Option.none(),
		);
	});

	it("rebinds execution-scoped client, catalog, and context without rebinding operations", () => {
		const client = createMockHevyClient();
		const operations = createOperations(client);
		const runtime = createToolRuntime({
			client,
			operations,
			catalog,
		});
		const signal = new AbortController().signal;
		const scoped = runtime.forExecution({ signal, deadline: 456 });
		const parentServices = resolveRuntimeServices(runtime);
		const scopedServices = resolveRuntimeServices(scoped);

		expect(Context.get(parentServices, HevyClientService)).toBe(client);
		expect(Context.get(scopedServices, HevyClientService)).toBe(
			scoped.getClient(),
		);
		expect(Context.get(scopedServices, HevyClientService)).not.toBe(client);
		expect(Context.get(scopedServices, ExerciseTemplateCatalogService)).toBe(
			scoped.catalog,
		);
		expect(scoped.catalog).not.toBe(catalog);
		expect(Context.get(scopedServices, ToolExecutionContextService)).toBe(
			scoped.execution,
		);
		expect(Context.get(scopedServices, HevyOperationsService)).toBe(operations);
		expect(Context.get(parentServices, ExerciseTemplateCatalogService)).toBe(
			catalog,
		);
		expect(Context.get(parentServices, HevyOperationsService)).toBe(operations);
	});
});

describe("createToolRuntime handler factory composition", () => {
	it("invokes the caller-supplied createHandler when an observer is configured", async () => {
		const finish = vi.fn();
		const start = vi.fn(() => ({ run: runImmediately, finish }));
		const customHandler: ToolHandler = () =>
			Promise.resolve({ content: [{ type: "text", text: "custom" }] });
		const createHandler: ToolHandlerFactory = vi.fn(() => customHandler);
		const runtime = createToolRuntime({
			client: null,
			catalog,
			createHandler,
			observer: { start },
		});

		const handler = runtime.createHandler(
			() => Effect.succeed({ content: [{ type: "text", text: "default" }] }),
			"get-workout",
		);

		await expect(handler({})).resolves.toMatchObject({
			content: [{ text: "custom" }],
		});
		expect(createHandler).toHaveBeenCalledOnce();
		expect(createHandler).toHaveBeenCalledWith(
			expect.any(Function),
			"get-workout",
			undefined,
		);
		expect(start).toHaveBeenCalledOnce();
		expect(finish).toHaveBeenCalledWith(
			expect.objectContaining({ outcome: "success" }),
		);
	});

	it("observes and wraps errors thrown by a custom createHandler handler", async () => {
		const finish = vi.fn();
		const start = vi.fn(() => ({ run: runImmediately, finish }));
		const stderr = vi.spyOn(console, "error").mockImplementation(() => {});
		const runtime = createToolRuntime({
			client: null,
			catalog,
			createHandler: () => (): Promise<McpToolResponse> =>
				Promise.reject(new Error("custom failure sentinel")),
			observer: { start },
		});

		const result = await runtime.createHandler(
			() => Effect.succeed({ content: [] }),
			"get-workout",
		)({});

		expect(result).toMatchObject({ isError: true });
		expect(finish).toHaveBeenCalledWith(
			expect.objectContaining({ outcome: "thrown_error" }),
		);
		stderr.mockRestore();
	});

	it("keeps the caller-supplied createHandler when no observer is configured", async () => {
		const start = vi.fn();
		const customHandler: ToolHandler = () =>
			Promise.resolve({ content: [{ type: "text", text: "custom" }] });
		const createHandler: ToolHandlerFactory = vi.fn(() => customHandler);
		const runtime = createToolRuntime({
			client: null,
			catalog,
			createHandler,
			observer: undefined,
		});

		await expect(
			runtime.createHandler(
				() => Effect.succeed({ content: [{ type: "text", text: "default" }] }),
				"get-workout",
			)({}),
		).resolves.toMatchObject({ content: [{ text: "custom" }] });
		expect(createHandler).toHaveBeenCalledOnce();
		expect(start).not.toHaveBeenCalled();
	});
});

describe("createToolRuntime observation scope", () => {
	it("does not execute a write handler twice when run instrumentation fails", async () => {
		let executions = 0;
		const finish = vi.fn();
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: () => {
						throw new Error("instrumentation failed");
					},
					finish,
				}),
			},
		});
		const handler = runtime.createHandler(() => {
			executions += 1;
			return Effect.succeed({ content: [{ type: "text", text: "ok" }] });
		}, "create-workout");

		await expect(handler({ id: "workout-id" })).resolves.toMatchObject({
			content: [{ text: "ok" }],
		});
		expect(executions).toBe(1);
		expect(finish).toHaveBeenCalledOnce();
	});

	it("starts the handler lazily inside the active observer scope", async () => {
		let active = false;
		const handler = vi.fn(() => {
			expect(active).toBe(true);
			return Effect.succeed({
				content: [{ type: "text" as const, text: "ok" }],
			});
		});
		let runCalls = 0;
		const run = async <T>(operation: () => Promise<T>): Promise<T> => {
			runCalls += 1;
			active = true;
			try {
				return await operation();
			} finally {
				active = false;
			}
		};
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: { start: () => ({ run, finish: vi.fn() }) },
		});
		await runtime.createHandler(handler, "get-workout")({ workout_id: "id" });

		expect(runCalls).toBe(1);
		expect(handler).toHaveBeenCalledOnce();
	});

	it("reuses the handler result when run fails after invoking it", async () => {
		const handler = vi
			.fn()
			.mockReturnValue(
				Effect.succeed({ content: [{ type: "text", text: "ok" }] }),
			);
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: async (operation) => {
						await operation();
						throw new Error("observer failed after execution");
					},
					finish: vi.fn(),
				}),
			},
		});

		await expect(
			runtime.createHandler(handler, "create-workout")({}),
		).resolves.toMatchObject({ content: [{ text: "ok" }] });
		expect(handler).toHaveBeenCalledOnce();
	});

	it("emits only allowlisted taxonomy and bounded argument structure", async () => {
		const start = vi.fn(() => ({
			run: runImmediately,
			finish: vi.fn(),
		}));
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: { start },
		});
		const secret = "private-routine-title-sentinel";
		const handler = runtime.createHandler(
			() => Effect.succeed({ content: [] }),
			"list-routines",
			{ feature: "routines", kind: "read", operation: "list" },
		);

		await handler({
			page: 12,
			page_size: 5,
			query: secret,
			workout_id: "private-workout-id",
			include_custom: true,
			private_note: secret,
		});

		expect(start).toHaveBeenCalledWith({
			name: "list-routines",
			taxonomy: { feature: "routines", kind: "read", operation: "list" },
			argumentKeys: [
				"page",
				"page_size",
				"workout_id",
				"include_custom",
				"query",
			],
			argumentPresence: { workout_id: true, query: true },
			numericArgumentBuckets: { page: "11-50", page_size: "2-10" },
			booleanArguments: { include_custom: true },
			argumentKeyCountBucket: "2-10",
		});
		expect(JSON.stringify(start.mock.calls)).not.toContain(secret);
		expect(JSON.stringify(start.mock.calls)).not.toContain(
			"private-workout-id",
		);
		expect(JSON.stringify(start.mock.calls)).not.toContain("privateNote");
	});

	it("reports bounded result content counts", async () => {
		const finish = vi.fn();
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: (operation) => operation(),
					finish,
				}),
			},
		});
		const content = Array.from({ length: 12 }, (_, index) => ({
			type: "text" as const,
			text: `result-${index}`,
		}));

		await runtime.createHandler(
			() => Effect.succeed({ content }),
			"list-workouts",
		)({});

		expect(finish).toHaveBeenCalledWith(
			expect.objectContaining({
				result: expect.objectContaining({ contentCountBucket: "11-50" }),
			}),
		);
		expect(JSON.stringify(finish.mock.calls)).not.toContain(
			'"contentCount":12',
		);
	});

	it("reports a safe thrown-error diagnostic without exception text", async () => {
		const finish = vi.fn();
		const secret = "private-handler-error-sentinel";
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: (operation) => operation(),
					finish,
				}),
			},
		});
		const stderr = vi.spyOn(console, "error").mockImplementation(() => {});

		const result = await runtime.createHandler(
			() => Effect.fail(new Error(secret)),
			"get-workouts",
		)({});

		expect(result).toMatchObject({ isError: true });
		expect(finish).toHaveBeenCalledWith(
			expect.objectContaining({
				outcome: "thrown_error",
				errorType: "UNKNOWN_ERROR",
				error: expect.objectContaining({ category: "Error" }),
			}),
		);
		expect(JSON.stringify(finish.mock.calls)).not.toContain(secret);
		stderr.mockRestore();
	});

	it("lets the newest nested execution scope control the client", async () => {
		const client = createMockHevyClient();
		const getUserInfo = client.getUserInfo.mockResolvedValue({
			data: { id: "user" },
		});
		const runtime = createToolRuntime({ client, catalog });
		const firstSignal = new AbortController().signal;
		const secondSignal = new AbortController().signal;
		const first = runtime.forExecution({
			signal: firstSignal,
			deadline: 111,
		});
		const second = first.forExecution({
			signal: secondSignal,
			deadline: 222,
		});

		expect(second.executionDeadline).toBe(222);
		await second.getClient().getUserInfo();

		expect(getUserInfo).toHaveBeenCalledWith({
			signal: secondSignal,
			deadline: 222,
		});
	});

	it("cleans up fallback listeners across repeated execution scopes", () => {
		const nativeDescriptor = Object.getOwnPropertyDescriptor(
			AbortSignal,
			"any",
		);
		Object.defineProperty(AbortSignal, "any", {
			value: undefined,
			configurable: true,
		});
		try {
			const lifecycle = new AbortController();
			const removeEventListener = vi.spyOn(
				lifecycle.signal,
				"removeEventListener",
			);
			const runtime = createToolRuntime({
				client: null,
				catalog,
				lifecycleSignal: lifecycle.signal,
			});

			for (let index = 0; index < 3; index += 1) {
				const request = new AbortController();
				const scoped = runtime.forExecution({ signal: request.signal });
				request.abort();
				expect(scoped.execution?.signal?.aborted).toBe(true);
			}

			expect(removeEventListener).toHaveBeenCalledTimes(3);
		} finally {
			if (nativeDescriptor) {
				Object.defineProperty(AbortSignal, "any", nativeDescriptor);
			} else {
				Reflect.deleteProperty(AbortSignal, "any");
			}
		}
	});
});

import { Cache, Effect } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it, vi } from "vitest";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import {
	createExerciseTemplateCatalog,
	type ExerciseTemplateCatalog,
	type ExerciseTemplateCatalogCache,
	EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
	EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
} from "./exercise-template-catalog.js";

type ListAll = Pick<TemplatesListAllOperation, "effect">;
type ListAllError = Effect.Error<ReturnType<ListAll["effect"]>>;

function createCatalog(
	listAll: ListAll,
	cache?: ExerciseTemplateCatalogCache,
): ExerciseTemplateCatalog {
	const serverCache =
		cache ??
		Effect.runSync(
			Cache.make({
				capacity: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
				timeToLive: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
				lookup: (_key: string) => listAll.effect(),
			}),
		);
	return createExerciseTemplateCatalog({ templates: { listAll } }, serverCache);
}

function operation(effect: ListAll["effect"]): ListAll {
	return { effect };
}

describe("exercise template catalog", () => {
	it("reset clears the server cache and forces a fresh catalog request", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValueOnce(Effect.succeed([{ id: "first" }]))
			.mockReturnValueOnce(Effect.succeed([{ id: "second" }]));
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		catalog.reset();
		await expect(catalog.get()).resolves.toMatchObject([{ id: "second" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("deduplicates concurrent cache misses", async () => {
		let resolveLookup: ((templates: ExerciseTemplate[]) => void) | undefined;
		const listAll = vi.fn<ListAll["effect"]>().mockImplementation(() =>
			Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
				resolveLookup = (templates) => resume(Effect.succeed(templates));
			}),
		);
		const catalog = createCatalog(operation(listAll));

		const first = Effect.runPromise(catalog.effect());
		const second = Effect.runPromise(catalog.effect());
		await Promise.resolve();
		expect(listAll).toHaveBeenCalledOnce();

		resolveLookup?.([{ id: "shared", title: "Shared" }]);
		await expect(Promise.all([first, second])).resolves.toEqual([
			[{ id: "shared", title: "Shared" }],
			[{ id: "shared", title: "Shared" }],
		]);
	});

	it("does not share controlled calls between independently cancellable callers", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation((options?: HevyExecutionOptions) =>
				Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
					const signal = options?.signal;
					if (signal?.aborted) {
						resume(Effect.fail(signal.reason));
						return;
					}
					const onAbort = () =>
						resume(Effect.fail(signal?.reason ?? new Error("aborted")));
					signal?.addEventListener("abort", onAbort, { once: true });
					const template =
						signal === firstController.signal ? "first" : "second";
					const timer = setTimeout(
						() => resume(Effect.succeed([{ id: template }])),
						template === "first" ? 100 : 20,
					);
					return Effect.sync(() => {
						clearTimeout(timer);
						signal?.removeEventListener("abort", onAbort);
					});
				}),
			);
		const catalog = createCatalog(operation(listAll));

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		firstController.abort(new DOMException("first canceled", "AbortError"));

		await expect(first).rejects.toMatchObject({ name: "AbortError" });
		await expect(second).resolves.toMatchObject([{ id: "second" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("uses templates.listAll rather than a Promise client for lookup", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValue(
				Effect.succeed([{ id: "template-1", title: "Template 1" }]),
			);
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).resolves.toEqual([
			{ id: "template-1", title: "Template 1" },
		]);
		expect(listAll).toHaveBeenCalledOnce();
	});

	it("reloads after the five-minute TTL", async () => {
		let calls = 0;
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation(() =>
				Effect.succeed([{ id: `template-${++calls}` }]),
			);
		const catalog = createCatalog(operation(listAll));
		const program = Effect.gen(function* () {
			const first = yield* catalog.effect();
			yield* TestClock.adjust(
				`${EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS} millis`,
			);
			const second = yield* catalog.effect();
			return [first, second] as const;
		});

		await expect(
			Effect.runPromise(Effect.provide(program, TestClock.layer())),
		).resolves.toEqual([[{ id: "template-1" }], [{ id: "template-2" }]]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("invalidates a failed lookup before the next call", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValueOnce(Effect.fail(new Error("temporary failure")))
			.mockReturnValueOnce(Effect.succeed([{ id: "recovered" }]));
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).rejects.toThrow("temporary failure");
		await expect(catalog.get()).resolves.toMatchObject([{ id: "recovered" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("does not let an older controlled load replace a newer result", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		const pending: Array<{
			signal: AbortSignal | undefined;
			resume: (effect: Effect.Effect<ExerciseTemplate[]>) => void;
		}> = [];
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation((options?: HevyExecutionOptions) =>
				Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
					pending.push({ resume, signal: options?.signal });
				}),
			);
		const catalog = createCatalog(operation(listAll));

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		await vi.waitFor(() => expect(pending).toHaveLength(2));

		pending[1]?.resume(Effect.succeed([{ id: "newer" }]));
		await expect(second).resolves.toMatchObject([{ id: "newer" }]);
		pending[0]?.resume(Effect.succeed([{ id: "older" }]));
		await expect(first).resolves.toMatchObject([{ id: "older" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "newer" }]);
		expect(pending.map(({ signal }) => signal)).toEqual([
			firstController.signal,
			secondController.signal,
		]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});
});

import { describe, expect, it, vi } from "vitest";
import {
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HevyHttpError,
} from "@hevy-mcp/hevy-client";
import { ErrorType } from "./error-policy.js";
import { createErrorResponse, withErrorHandling } from "./error-handler.js";
import { SafeUserError } from "./safe-user-error.js";

type ErrorPayload = { readonly error: string };

function httpError(
	status: number,
	data?: ErrorPayload,
	headers?: Headers,
	method = "GET",
	endpoint = "/v1/user/info",
) {
	return new HevyHttpError(`HTTP ${status}`, {
		status,
		statusText: "Error",
		data,
		headers,
		method,
		endpoint,
	});
}

describe("createErrorResponse", () => {
	it("formats ordinary errors with context", () => {
		const result = createErrorResponse(
			new Error("Bearer secret-ordinary-error"),
			"test-tool",
		);
		expect(result).toMatchObject({
			isError: true,
			content: [
				{
					type: "text",
					text: "[test-tool] Error: The request failed unexpectedly. Please try again.",
				},
			],
		});
		expect(JSON.stringify(result)).not.toContain("secret-ordinary-error");
	});

	it("emits the canonical bounded failure event", () => {
		const stderrSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		try {
			createErrorResponse(httpError(500), "get-workouts");
			expect(stderrSpy).toHaveBeenCalledWith(
				JSON.stringify({
					event: "mcp.tool.failure",
					"mcp.tool.name": "get-workouts",
					"error.type": ErrorType.API_ERROR,
					"error.category": "HevyHttpError",
					"http.status_code": 500,
					"http.method": "GET",
					"hevy.api.endpoint": "/v1/user/info",
					"hevy.api.outcome": "terminal_failure",
					"hevy.api.phase": "before-dispatch",
					"hevy.api.operation_safety": "read",
					"hevy.api.commit_state": "not_sent",
					"hevy.api.safe_to_retry": false,
				}),
			);
		} finally {
			stderrSpy.mockRestore();
		}
	});

	it("renders caller cancellation as a client cancellation", () => {
		const result = createErrorResponse(
			new HevyHttpError("The request was canceled by the client.", {
				method: "GET",
				endpoint: "/v1/user/info",
				code: HEVY_REQUEST_ABORTED_ERROR_CODE,
				outcome: "cancelled",
			}),
			"get-user",
		);

		expect(result.content[0]?.text).toBe(
			"[get-user] Error: The request was canceled by the client.",
		);
		expect(result.content[0]?.text).not.toContain("Hevy API request");
	});

	it("classifies the original error message when the safe message is generic", () => {
		const result = createErrorResponse(
			new Error("request validation failed"),
			"test-tool",
		);
		expect(result.errorContext).toMatchObject({
			errorType: ErrorType.VALIDATION_ERROR,
		});
	});

	it("only exposes explicitly safe user errors and bounds their messages", () => {
		const longMessage = "validation failed ".repeat(100);
		const result = createErrorResponse(new Error(longMessage), "test-tool");
		const safeResult = createErrorResponse(
			new SafeUserError(longMessage),
			"test-tool",
		);

		expect(result.content[0]?.text).toBe(
			"[test-tool] Error: The request failed unexpectedly. Please try again.",
		);
		expect(safeResult.content[0]?.text).toBe(
			`[test-tool] Error: ${longMessage.slice(0, 512)}`,
		);
	});

	it("gives routine update 404s actionable guidance", () => {
		const result = createErrorResponse(
			httpError(404, undefined, undefined, "PUT", "/v1/routines/:routineId"),
		);
		expect(result.content[0]?.text).toContain(
			"The requested routine was not found in Hevy. It may have been deleted or the routine ID is incorrect.",
		);
	});

	it.each([
		[401, "The Hevy API key is invalid or has expired"],
		[404, "The requested resource was not found"],
		[400, "The request failed Hevy validation"],
		[409, "A conflict occurred because the resource already exists"],
		[422, "The request failed Hevy validation"],
		[503, "Hevy API experienced an error"],
	])("maps HTTP %s to a safe Hevy message", (status, expected) => {
		const result = createErrorResponse(httpError(status));
		expect(result.content[0]?.text).toContain(expected);
		if (status === 409) {
			expect(result.content[0]?.text).toBe(
				"Error: A conflict occurred because the resource already exists or conflicts with the current server state. Check whether it already exists and use the update tool when appropriate.",
			);
		}
	});

	it("gives body measurement create conflicts actionable guidance", () => {
		const result = createErrorResponse(
			httpError(409, undefined, undefined, "POST", "/v1/body_measurements"),
		);
		expect(result.content[0]?.text).toBe(
			"Error: A body measurement already exists for this date. Use the update-body-measurement tool to modify it.",
		);
	});

	it("surfaces only sanitized upstream validation detail", () => {
		const secret = "Bearer upstream-secret-value";
		const error = httpError(400, {
			error: `Routine is invalid; Authorization: ${secret}`,
		});
		error.message = "untrusted raw message";
		error.code = "untrusted-code";
		const stderrSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		try {
			const result = createErrorResponse(error);
			expect(result.content[0]?.text).toContain(
				"The request failed Hevy validation. Check the field values and try again. Detail: Routine is invalid; Authorization: [REDACTED]",
			);
			expect(JSON.stringify(result)).not.toContain(secret);
			expect(JSON.stringify(stderrSpy.mock.calls)).not.toContain(secret);
		} finally {
			stderrSpy.mockRestore();
		}
	});

	it("omits hostile HTTP metadata from retained debug context", () => {
		const secret = "sentinel-http-context";
		const error = new HevyHttpError(secret, {
			status: 999,
			statusText: secret,
			method: secret,
			endpoint: `https://attacker.example/${secret}`,
			code: secret,
			headers: new Headers({ authorization: secret }),
			data: { secret },
			cause: new Error(secret),
		});
		const stderrSpy = vi.spyOn(console, "error").mockImplementation(() => {});

		const result = createErrorResponse(error);

		expect(result.errorContext).toEqual(
			expect.objectContaining({ axios: undefined }),
		);
		expect(JSON.stringify(result.errorContext)).not.toContain(secret);
		expect(JSON.stringify(stderrSpy.mock.calls)).not.toContain(secret);
		stderrSpy.mockRestore();
	});

	it("includes bounded Retry-After guidance for rate limits", () => {
		const result = createErrorResponse(
			httpError(429, undefined, new Headers({ "retry-after": "3" })),
		);
		expect(result.content[0]?.text).toContain("about 3 seconds");
	});

	it("accepts bounded numeric and array Retry-After header records", () => {
		const numericHeaderError = httpError(429);
		Object.defineProperty(numericHeaderError, "headers", {
			value: { "retry-after": 1 },
		});
		const arrayHeaderError = httpError(429);
		Object.defineProperty(arrayHeaderError, "headers", {
			value: { "RETRY-AFTER": ["2", "ignored"] },
		});

		expect(createErrorResponse(numericHeaderError).content[0]?.text).toContain(
			"about 1 second",
		);
		expect(createErrorResponse(arrayHeaderError).content[0]?.text).toContain(
			"about 2 seconds",
		);
	});

	it("handles HTTP-date, missing, and malformed Retry-After guidance", () => {
		vi.useFakeTimers();
		vi.setSystemTime(new Date("2026-07-11T12:00:00.000Z"));
		try {
			const dateResult = createErrorResponse(
				httpError(
					429,
					undefined,
					new Headers({
						"retry-after": "Sat, 11 Jul 2026 12:00:05 GMT",
					}),
				),
			);
			const missingResult = createErrorResponse(httpError(429));
			const malformedResult = createErrorResponse(
				httpError(429, undefined, new Headers({ "retry-after": "not-a-date" })),
			);

			expect(dateResult.content[0]?.text).toContain("about 5 seconds");
			expect(missingResult.content[0]?.text).toContain(
				"Please wait and retry your request",
			);
			expect(malformedResult.content[0]?.text).toContain(
				"Please wait and retry your request",
			);
		} finally {
			vi.useRealTimers();
		}
	});

	it("classifies exhausted retries as network errors", () => {
		const error = httpError(503);
		error.hevyRetryExhausted = true;
		error.hevyRetryCount = 2;
		const result = createErrorResponse(error);
		expect(result.errorContext).toMatchObject({
			errorType: ErrorType.NETWORK_ERROR,
		});
		expect(result.content[0]?.text).toContain("after 3 attempts");
	});

	it("uses generic retry exhaustion guidance without a finite retry count", () => {
		const error = httpError(503);
		error.hevyRetryExhausted = true;
		error.hevyRetryCount = Number.NaN;

		const result = createErrorResponse(error);

		expect(result.content[0]?.text).toContain("after multiple attempts");
	});

	it("does not expose non-Error thrown values in client responses", () => {
		type CyclicThrownValue = { self?: CyclicThrownValue };
		const cyclic: CyclicThrownValue = {};
		cyclic.self = cyclic;
		const cases: unknown[] = [
			"Bearer secret-string",
			{ message: "secret-object-message" },
			{ reason: "secret-structured-value" },
			cyclic,
			17,
		];

		for (const thrownValue of cases) {
			const result = createErrorResponse(thrownValue);
			expect(result.content[0]?.text).toContain(
				"The request failed unexpectedly",
			);
			expect(JSON.stringify(result)).not.toContain("secret-");
		}
	});

	it("does not include full URLs or credentials in HTTP debug context", () => {
		const result = createErrorResponse(httpError(500));
		expect(result.errorContext).toMatchObject({
			axios: { method: "GET", url: "/v1/user/info", status: 500 },
		});
		expect(JSON.stringify(result)).not.toContain("api-key");
	});
});

