	operationsOverride?: HevyOperations,
) {
	const operations =
		operationsOverride ?? (client ? createOperations(client) : undefined);
	const listAll: TemplatesListAllOperation = {
		descriptor: {
			id: "templates.listAll",
			safety: "read",
		},
		effect: () => Effect.succeed([]),
		execute: () => Promise.resolve([]),
	};
